def CZeroSumFiniteColumnBound (T : ∀ i, E i →L[𝕜] F) (C : ℝ) : Prop :=
  ∀ (x : ∀ i, E i) (s : Finset I) (M : ℝ), 0 ≤ M →
    (∀ i ∈ s, ‖x i‖ ≤ M) → ‖∑ i ∈ s, T i (x i)‖ ≤ C * M

