theorem cZeroSum_columns_summable (T : ∀ i, E i →L[𝕜] F) {C : ℝ}
    (hC : 0 ≤ C) (hT : CZeroSumFiniteColumnBound T C) (x : JLMS.CZeroSum 𝕜 E) :
    Summable (fun i => T i (x i))

theorem norm_cZeroSum_columns_tsum_le (T : ∀ i, E i →L[𝕜] F) {C : ℝ}
